from fastapi.exceptions import HTTPException
from fastapi import APIRouter
from server.models.GameState import BaseGameState, GameState, UpsertGameState
from server.database.db import SessionDep
import uuid

router = APIRouter(prefix="/user", tags=["user"])


@router.put("/game-state", response_model=GameState)
async def save_game_state(state: UpsertGameState, session: SessionDep):
    # 1. Try to find the game in the DB using the ID from the payload
    # Note: If the user didn't send an ID, 'state.id' is a BRAND NEW random UUID 
    # generated by Pydantic, so existing_game will be None.
    existing_game = None
    if state.id:
        existing_game = session.get(GameState, state.id)

    if existing_game:
        # --- SCENARIO: UPDATE ---
        # The ID exists in the DB, so we update the record
        game_data = state.model_dump(exclude_unset=True)
        existing_game.sqlmodel_update(game_data)
        
        session.add(existing_game)
        session.commit()
        session.refresh(existing_game)
        return existing_game

    else:
        # --- SCENARIO: CREATE NEW ---
        # The ID does not exist in the DB.
        # This happens if:
        # A) The user sent no ID (state.id is a fresh random UUID) -> We insert it.
        # B) The user sent a specific ID that isn't in the DB yet -> We insert it.
        db_state = GameState.model_validate(state)
        session.add(db_state)
        session.commit()
        session.refresh(db_state)
        return db_state


@router.get("/game-state/{id}", response_model=GameState)
async def get_game_state(id: uuid.UUID, session: SessionDep):
    """Get the current game state."""
    existing_game = session.get(GameState, id)
    if not existing_game:
        raise HTTPException(status_code=404, detail="Game state not found")

    return existing_game